'use strict';
const accountBox=document.createElement('div');accountBox.className='account-box';accountBox.innerHTML='<button type="button" class="secondary-button" id="account-open">登录 / 云端记录</button>';document.querySelector('.workspace-nav').append(accountBox);
const accountDialog=document.createElement('dialog');accountDialog.className='flight-dialog account-dialog';accountDialog.innerHTML=`<div class="dialog-heading"><h2>账号与云端记录</h2><button type="button" class="dialog-close" id="account-close" aria-label="关闭">×</button></div><div id="account-guest"><form id="account-login"><label for="account-email">邮箱</label><input id="account-email" type="email" required autocomplete="email" placeholder="你的邮箱"><button type="submit" class="primary" id="account-send">发送登录链接</button></form><p>打开邮件里的链接完成登录，无需设置密码。未登录时可以继续使用游客模式。</p></div><div id="account-user" hidden><p id="account-email-label"></p><div class="account-actions"><button type="button" class="secondary-button" id="account-pull">从云端恢复</button><button type="button" class="primary" id="account-push">保存到云端</button><button type="button" class="secondary-button" id="account-merge">导入本机游客记录</button><button type="button" class="text-button" id="account-signout">退出登录</button></div><p>当前账号的记录在本机自动保存。跨设备使用时，请先恢复云端记录；完成修改后保存到云端。</p></div><p id="account-message" role="status" aria-live="polite"></p>`;document.body.append(accountDialog);
let atlasClient=null,accountId=null,cloudRevision=null,accountBusy=false,accountQueue=Promise.resolve();
const accountMessage=(text,bad=false)=>{$('account-message').textContent=text;$('account-message').style.color=bad?'#a55241':'#617e76';};
function accountLock(busy){accountBusy=busy;document.querySelector('main').inert=busy;accountDialog.querySelectorAll('button').forEach(b=>b.disabled=busy);}
async function accountAction(task){if(accountBusy)return;accountLock(true);try{await task();}catch(e){accountMessage(e.message||'操作失败，请稍后重试。',true);}finally{accountLock(false);}}
async function readDraftKey(key){const db=await draftDB;return new Promise((resolve,reject)=>{const r=db.transaction('drafts').objectStore('drafts').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function loadAccountDraft(key){await draftWrites;draftEpoch++;draftKey=key;draftTouched=false;state.rows=null;state.sheets=[];state.fileName='';state.colors=atlasColors(null);state.labelSelection=null;$('future').checked=false;syncAtlasColorControls();$('record-search').value='';$('record-filter').value='all';$('record-year').value='all';$('record-aircraft').value='all';await restoreLocalDraft();if(state.rows===null)await regenerate();}
async function onAccountSession(session){await draftRestoreReady;await importQueue;const id=session?.user?.id||null;if(id===accountId)return;accountLock(true);try{await loadAccountDraft(id?'user:'+id:'current');accountId=id;cloudRevision=null;$('account-guest').hidden=!!id;$('account-user').hidden=!id;$('account-open').textContent=id?'我的账号':'登录 / 云端记录';$('account-email-label').textContent=session?.user?.email||'';accountMessage(id?'已登录。可从云端恢复记录，或导入本机游客记录。':'已退出，当前显示游客记录。');}catch(e){accountMessage('切换账号失败，请刷新页面后重试。',true);}finally{accountLock(false);}}
function cloudError(error){if(error.code==='40001')return Error('另一台设备已更新云端记录，请先从云端恢复，再保存修改。');if(['42P01','PGRST202','PGRST205'].includes(error.code))return Error('云端数据库尚未完成配置，请先运行 Supabase 数据库脚本。');return Error(error.message||'云端操作失败，请检查网络后重试。');}
async function fetchCloud(){const {data,error}=await atlasClient.from('atlas_drafts').select('payload,revision').eq('user_id',accountId).maybeSingle();if(error)throw cloudError(error);return data;}
$('account-open').addEventListener('click',()=>accountDialog.showModal());$('account-close').addEventListener('click',()=>accountDialog.close());
$('account-login').addEventListener('submit',e=>{e.preventDefault();accountAction(async()=>{if(!atlasClient)throw Error('登录服务尚未加载，请刷新后重试。');const {error}=await atlasClient.auth.signInWithOtp({email:$('account-email').value.trim(),options:{emailRedirectTo:location.origin+location.pathname}});if(error)throw error;accountMessage('登录邮件已发送，请在邮箱中打开链接。');});});
$('account-pull').addEventListener('click',()=>accountAction(async()=>{const cloud=await fetchCloud();if(!cloud){cloudRevision=0;accountMessage('账号还没有云端记录，可以保存当前记录。');return;}if(!validSnapshot(cloud.payload))throw Error('云端记录格式无法读取，本机数据未改动。');if(state.rows?.length&&!confirm('用云端记录替换当前账号在本机的记录与配色？未保存到云端的修改会被替换。'))return;await draftWrites;await draftTransaction(await draftDB,'readwrite',s=>s.put(cloud.payload,draftKey));await loadAccountDraft(draftKey);cloudRevision=cloud.revision;accountMessage('云端记录已恢复。');}));
$('account-push').addEventListener('click',()=>accountAction(async()=>{if(cloudRevision===null){const cloud=await fetchCloud();if(cloud)throw Error('请先从云端恢复已有记录，再保存，避免覆盖其他设备的数据。');cloudRevision=0;}await draftWrites;const snapshot=localSnapshot();if(!confirm(`将当前账号的 ${state.rows?.length||0} 条记录和图片设置保存到云端？`))return;const {data,error}=await atlasClient.rpc('save_atlas_draft',{draft:snapshot,expected_revision:cloudRevision});if(error)throw cloudError(error);cloudRevision=data;accountMessage('已保存到云端。');}));
$('account-merge').addEventListener('click',()=>accountAction(async()=>{const guest=await readDraftKey('current');if(!guest||!validSnapshot(guest)){accountMessage('本机没有可导入的游客记录。');return;}const rows=guest.sheets.length?guest.sheets.flatMap(s=>s.rows):guest.rows||[];if(!confirm(`将 ${rows.length} 条游客记录合并到当前账号？游客原始记录会保留。`))return;const old=state.rows?.length||0;state.rows=uniqueFlightRows([...(state.rows||[]),...rows]).rows;state.sheets=[{name:'航班记录',rows:state.rows}];await regenerate();await draftWrites;accountMessage(`已合并新增 ${state.rows.length-old} 条记录，请保存到云端。`);}));
$('account-signout').addEventListener('click',()=>accountAction(async()=>{await draftWrites;const {error}=await atlasClient.auth.signOut({scope:'local'});if(error)throw error;}));
async function startAtlasAccount(){try{if(!window.supabase)throw Error('登录组件加载失败，游客模式仍可使用。');atlasClient=window.supabase.createClient(ATLAS_AUTH_CONFIG.url,ATLAS_AUTH_CONFIG.publishableKey);atlasClient.auth.onAuthStateChange((event,session)=>{if(['INITIAL_SESSION','SIGNED_IN','SIGNED_OUT'].includes(event)){accountQueue=accountQueue.then(()=>onAccountSession(session)).catch(()=>accountMessage('账号状态更新失败，请刷新后重试。',true));}});}catch(e){accountMessage(e.message,true);}}
startAtlasAccount();
